import pandas as pd

def find_trending_hashtags(tweets: pd.DataFrame) -> pd.DataFrame:
    df = tweets.copy()
    df['tweet_date'] = pd.to_datetime(df['tweet_date'])
    df = df[(df['tweet_date'] >= '2024-02-01') & (df['tweet_date'] <= '2024-02-29')]
    if df.empty:
        return pd.DataFrame(columns=['hashtag', 'hashtag_count'])
    df['hashtag'] = df['tweet'].str.extract(r'(#[A-Za-z0-9_]+)')
    res = df.groupby('hashtag').size().reset_index(name='hashtag_count')
    return res.sort_values(by=['hashtag_count', 'hashtag'], ascending=[False, False]).head(3)
